/**
 * Builds an inline, decorative icon.
 *
 * @param {string} name - key of ICON_PATHS.
 * @returns {SVGSVGElement}
 * @throws {RangeError} when the name matches no icon.
 */
function icon(name) {
  const d = ICON_PATHS[name];
  if (!d) throw new RangeError('unknown icon: ' + name);

  const svg = document.createElementNS(ICON_NS, 'svg');
  svg.setAttribute('viewBox', '0 0 256 256');
  svg.setAttribute('fill', 'currentColor');
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');
  svg.classList.add('icon');

  const path = document.createElementNS(ICON_NS, 'path');
  path.setAttribute('d', d);
  svg.appendChild(path);
  return svg;
}

/**
 * Fills in the icons of every element carrying data-icon, without duplicates.
 *
 * Markup declares the name, the script supplies the path: no SVG is copied
 * into viewer.html.
 *
 * @param {ParentNode} [root=document]
 * @returns {void}
 */
function paintIcons(root = document) {
  for (const el of root.querySelectorAll('[data-icon]')) {
    if (el.querySelector('svg.icon')) continue;
    try {
      el.prepend(icon(el.dataset.icon));
    } catch (e) {
      console.warn('[pca]', e.message);
    }
  }
}
